const actual=checkCard($input.first().json.rows||[]);
if(actual.length!==candidate.matrix.length||fingerprint(actual)!==candidate.card_fingerprint)throw new Error('Fight Card read-back did not match the prepared card. Analysis is blocked; review the saved candidate and spreadsheet.');
return [{json:{...candidate,fight_card_status:'READY',initialized_at:new Date().toISOString()}}];

